insert into public.products (id, slug, kind, status, price_excl_vat, tone, sort_order, name, description, badge) values ('11111111-1111-4111-8111-000000000001', 'den-nguyet', 'single', 'published', 890000, 'amber', 1, '{"vi":"Đèn Nguyệt","en":"Nguyet Lantern","zh":"月灯"}'::jsonb, '{"vi":"Dáng tròn đầy, ánh sáng dịu như trăng rằm","en":"A full, round shape with light as soft as the full moon","zh":"圆润饱满，光线柔和如满月"}'::jsonb, null) on conflict (id) do nothing;
insert into public.products (id, slug, kind, status, price_excl_vat, tone, sort_order, name, description, badge) values ('11111111-1111-4111-8111-000000000002', 'den-vong', 'single', 'published', 1050000, 'dusk', 2, '{"vi":"Đèn Vọng","en":"Vong Lantern","zh":"望灯"}'::jsonb, '{"vi":"Thân thon cao, gợi nhớ mái đình làng cổ","en":"Tall and slender, recalling the roofs of old village temples","zh":"修长挺拔，令人想起古村亭阁的屋檐"}'::jsonb, '{"vi":"Bán chạy","en":"Best seller","zh":"畅销"}'::jsonb) on conflict (id) do nothing;
insert into public.products (id, slug, kind, status, price_excl_vat, tone, sort_order, name, description, badge) values ('11111111-1111-4111-8111-000000000003', 'den-sum-vay', 'set', 'published', 1680000, 'dawn', 3, '{"vi":"Đèn Sum Vầy","en":"Sum Vay Lantern Set","zh":"团圆灯组"}'::jsonb, '{"vi":"Bộ ba kích cỡ, dành tặng cả gia đình","en":"A set of three sizes, made for the whole family","zh":"三种尺寸一组，献给全家人"}'::jsonb, null) on conflict (id) do nothing;
insert into public.faq_entries (id, sort_order, is_published, question, answer) values ('22222222-2222-4222-8222-000000000001', 1, true, '{"vi":"Video và lời chúc lưu giữ được bao lâu?","en":"How long are the videos and messages kept?","zh":"视频和祝福会保存多久？"}'::jsonb, '{"vi":"Lời chúc dạng chữ được lưu vĩnh viễn. Lời chúc bằng giọng nói hoặc video được lưu 30 ngày kể từ khi người nhận bấm \"Tôi đã nhận được quà\" — hãy bấm \"Tải về\" để giữ lại. Video quá trình làm đèn (quét mã QR trên đèn) được lưu vĩnh viễn.","en":"Text messages are kept forever. Voice and video messages are kept for 30 days after the recipient taps \"I have received my gift\" — tap \"Download\" to keep a copy. The lantern-making video (scan the QR code on the lantern) is kept forever.","zh":"文字祝福永久保存。语音或视频祝福在收礼人点击“我已收到礼物”后保存 30 天——请点击“下载”保留副本。灯的制作视频（扫描灯上的二维码）永久保存。"}'::jsonb) on conflict (id) do nothing;
insert into public.faq_entries (id, sort_order, is_published, question, answer) values ('22222222-2222-4222-8222-000000000002', 2, true, '{"vi":"Tôi có thể chỉnh sửa lời chúc sau khi đặt hàng không?","en":"Can I edit my message after ordering?","zh":"下单后可以修改祝福吗？"}'::jsonb, '{"vi":"Có. Bạn chỉnh sửa lời chúc trong trang tài khoản. Phần chữ được khóa khi đơn đã đóng gói (vì thiệp viết tay đã được viết); giọng nói và video sửa được cho đến khi đơn được gửi đi.","en":"Yes. You can edit your message in your account. The text is locked once the order is packed (the handwritten card has been written); voice and video can be changed until the order ships.","zh":"可以。您可以在账户页面修改祝福。订单打包后文字将被锁定（手写卡片已写好）；语音和视频可修改至订单发货前。"}'::jsonb) on conflict (id) do nothing;
insert into public.faq_entries (id, sort_order, is_published, question, answer) values ('22222222-2222-4222-8222-000000000003', 3, true, '{"vi":"Người nhận có cần tải ứng dụng để xem không?","en":"Does the recipient need to install an app?","zh":"收礼人需要安装应用吗？"}'::jsonb, '{"vi":"Không cần. Chỉ cần quét mã bằng camera điện thoại, nội dung mở ngay trên trình duyệt.","en":"No. Just scan the code with the phone camera and the content opens in the browser.","zh":"不需要。只需用手机相机扫码，内容即在浏览器中打开。"}'::jsonb) on conflict (id) do nothing;
insert into public.faq_entries (id, sort_order, is_published, question, answer) values ('22222222-2222-4222-8222-000000000004', 4, true, '{"vi":"Đèn giấy dó có dễ vỡ khi vận chuyển không?","en":"Are dó paper lanterns fragile in shipping?","zh":"纸灯在运输中容易损坏吗？"}'::jsonb, '{"vi":"Khung tre và giấy dó được gia cố, đóng gói trong hộp có lớp đệm chuyên dụng cho hàng thủ công dễ vỡ.","en":"The bamboo frame and dó paper are reinforced and packed in a padded box made for fragile handicrafts.","zh":"竹架和纸面经过加固，并装入专为易碎手工艺品设计的缓冲盒中。"}'::jsonb) on conflict (id) do nothing;
insert into public.faq_entries (id, sort_order, is_published, question, answer) values ('22222222-2222-4222-8222-000000000005', 5, true, '{"vi":"Thời gian hoàn thành một chiếc đèn đặt riêng là bao lâu?","en":"How long does it take to make a lantern?","zh":"制作一盏灯需要多长时间？"}'::jsonb, '{"vi":"Trung bình 5–7 ngày làm việc, tuỳ theo mẫu và khối lượng đơn tại xưởng vào thời điểm đặt hàng.","en":"On average 5–7 working days, depending on the model and the workshop’s workload at the time of ordering.","zh":"平均 5–7 个工作日，视款式及下单时工坊的订单量而定。"}'::jsonb) on conflict (id) do nothing;
